import React from "react";
import Card from "../components/Card";

const InterviewPage = () => {
  return (
    <div>
      <h1>Interview Practice</h1>
      <Card>
        <h2>AI-Powered Interview Chat</h2>
        <p>Practice your interview skills with AI assistance.</p>
      </Card>
    </div>
  );
};

export default InterviewPage;
